216	// SaveTokens must never leave a fresh access token paired with a stale
217	// refresh token: the server single-use-rotates, so that pairing looks healthy
218	// until the access token expires, then the dead refresh token forces a
219	// re-login. The store persists refresh-first to invert both failure modes.
220	func TestContextTokenStore_SaveTokens_RefreshFirstOrdering(t *testing.T) {
221		t.Run("refresh write fails: access slot untouched", func(t *testing.T) {
222			svc := testCoreService
223			path := filepath.Join(t.TempDir(), "tokens.json")
224	
225			// Seed an existing good pair through a clean backend first — the fault
226			// backend installed below would reject the refresh-slot seed too.
227			oldAccess := makeJWT(t, fmt.Sprintf(`{"iss":"https://core.example","handle":"alice","exp":%d}`, time.Now().Add(time.Hour).Unix()))
228			seedRestore := tokenstore.UseFileBackendForTesting(path)
229			if err := tokenstore.Set(svc, "alice", tokenstore.EncodeTokenWithExpiration(oldAccess, 3600)); err != nil {
230				t.Fatalf("seed access: %v", err)
231			}
232			if err := tokenstore.Set(tokenstore.RefreshService(svc), "alice", "entr_old"); err != nil {
233				t.Fatalf("seed refresh: %v", err)
234			}
235			seedRestore()
236	
237			// Now point at the SAME file but fail any refresh-slot write.
238			failRefresh := func(service, _ string) bool { return service == tokenstore.RefreshService(svc) }
239			restore := tokenstore.UseFailingBackendForTesting(path, failRefresh)
240			t.Cleanup(restore)
241	
242			st := contextTokenStore{service: svc, handle: "alice"}
243			newAccess := makeJWT(t, fmt.Sprintf(`{"iss":"https://core.example","handle":"alice","exp":%d}`, time.Now().Add(2*time.Hour).Unix()))
244			err := st.SaveTokens("", tokens.TokenSet{AccessToken: newAccess, RefreshToken: "entr_new", ExpiresAt: time.Now().Add(2 * time.Hour)})
245			if err == nil {
246				t.Fatal("SaveTokens: want error when refresh write fails")
247			}
248			// The access slot must NOT have advanced — aborting before the access
249			// write preserves the old (still-mintable) pair.
250			enc, _ := tokenstore.Get(svc, "alice") //nolint:errcheck // read-back
251			if access, _ := tokenstore.DecodeTokenWithExpiration(enc); access != oldAccess {
252				t.Fatalf("access slot advanced despite refresh-write failure: a fresh access token is now paired with a stale refresh token")
253			}
254		})
255	
256		t.Run("access write fails: refresh slot already advanced (self-heals)", func(t *testing.T) {
257			svc := testCoreService
258			failAccess := func(service, _ string) bool { return service == svc }
259			restore := tokenstore.UseFailingBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"), failAccess)
260			t.Cleanup(restore)
261	
262			st := contextTokenStore{service: svc, handle: "alice"}
263			newAccess := makeJWT(t, fmt.Sprintf(`{"iss":"https://core.example","handle":"alice","exp":%d}`, time.Now().Add(2*time.Hour).Unix()))
264			err := st.SaveTokens("", tokens.TokenSet{AccessToken: newAccess, RefreshToken: "entr_new", ExpiresAt: time.Now().Add(2 * time.Hour)})
265			if err == nil {
266				t.Fatal("SaveTokens: want error when access write fails")
267			}
268			// Refresh-first means the rotated refresh token is already persisted, so
269			// the next load re-mints a fresh access token rather than replaying a
270			// dead refresh token.
271			if r, _ := tokenstore.Get(tokenstore.RefreshService(svc), "alice"); r != "entr_new" { //nolint:errcheck // read-back
272				t.Fatalf("refresh slot = %q, want entr_new persisted before the access write", r)
273			}
274		})
275	}
276	
277	func failRoundTripper(t *testing.T) http.RoundTripper {
278		t.Helper()
279		return roundTripFunc(func(r *http.Request) (*http.Response, error) {
280			t.Errorf("unexpected HTTP call to %s — a fresh token must not hit the network", r.URL)
281			return nil, errors.New("unexpected network call")
282		})
283	}
284	
285	type roundTripFunc func(*http.Request) (*http.Response, error)
286	
287	func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }
