// New returns a *Client wired to talk to the Entire control plane (Core
// API) as the currently logged-in user.
//
// The host and bearer come from auth.ResolveControlPlaneTarget: the active
// contexts.json login always wins (so `entire auth use <ctx>` retargets the
// control plane onto that login server), and ENTIRE_AUTH_BASE_URL / the
// default is used only as the fallback when no context is active — not as an
// override. The Core API is served at <host>/api/v1. The bearer is resolved
// lazily per request; for an active context it re-mints silently from the
// stored refresh token, and for the fallback path an RFC 8693 exchange
// happens transparently when the stored token's audience doesn't cover the
// host.
func New() (*Client, error) {
	target, err := auth.ResolveControlPlaneTarget()
	if err != nil {
		return nil, fmt.Errorf("resolve control-plane target: %w", err)
	}
	src := &providerSource{provide: target.TokenSource}
	client, err := NewClient(strings.TrimRight(target.CoreURL, "/")+apiBasePath, src)
	if err != nil {
		return nil, fmt.Errorf("build Entire API client: %w", err)
	}
	return client, nil
}

